def calc(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return (None, None)

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while True:
            t, _ = peek()
            if t == '+':
                pos += 1
                val += parse_term()
            elif t == '-':
                pos += 1
                val -= parse_term()
            else:
                break
        return val

    def parse_term():
        nonlocal pos
        val = parse_factor()
        while True:
            t, _ = peek()
            if t == '*':
                pos += 1
                val *= parse_factor()
            elif t == '/':
                pos += 1
                rhs = parse_factor()
                q = abs(val) // abs(rhs)
                if (val < 0) != (rhs < 0):
                    q = -q
                val = q
            else:
                break
        return val

    def parse_factor():
        nonlocal pos
        t, _ = peek()
        if t == '-':
            pos += 1
            return -parse_factor()
        return parse_primary()

    def parse_primary():
        nonlocal pos
        t, v = peek()
        if t == 'NUM':
            pos += 1
            return v
        elif t == '(':
            pos += 1
            val = parse_expr()
            t2, _ = peek()
            if t2 != ')':
                raise ValueError("Expected closing parenthesis")
            pos += 1
            return val
        else:
            raise ValueError(f"Unexpected token: {t}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

